import torch, triton, triton.language as tl

@triton.jit
def _trunc(x):
    return (x.to(tl.int32, bitcast=True) & -8192).to(tl.float32, bitcast=True)

# 4-product: hi*hi + hi*lo + lo*hi + lo*lo, 4 independent accumulators
@triton.jit
def _P4(x, y):
    x_hi=_trunc(x); x_lo=_trunc(x-x_hi); y_hi=_trunc(y); y_lo=_trunc(y-y_hi)
    c0=tl.dot(x_hi,y_hi,input_precision="tf32")
    c1=tl.dot(x_hi,y_lo,input_precision="tf32")
    c2=tl.dot(x_lo,y_hi,input_precision="tf32")
    c3=tl.dot(x_lo,y_lo,input_precision="tf32")
    return (c0+c1)+(c2+c3)

@triton.jit
def _BI(x,y): return tl.dot(x,y,input_precision="tf32x3")
@triton.jit
def _BI2(x,y): return tl.dot(x,y,input_precision="tf32")  # 1-pass for reference

@triton.jit
def _k(Xp,Yp,P4p,BIp,B1p,M:tl.constexpr,K:tl.constexpr,N:tl.constexpr):
    rm=tl.arange(0,M);rk=tl.arange(0,K);rn=tl.arange(0,N)
    x=tl.load(Xp+rm[:,None]*K+rk[None,:]); y=tl.load(Yp+rk[:,None]*N+rn[None,:])
    tl.store(P4p+rm[:,None]*N+rn[None,:], _P4(x,y))
    tl.store(BIp+rm[:,None]*N+rn[None,:], _BI(x,y))
    tl.store(B1p+rm[:,None]*N+rn[None,:], _BI2(x,y))

torch.manual_seed(0)
M,K,N=32,32,64
x=torch.randn(M,K,device="cuda").float(); y=torch.randn(K,N,device="cuda").float()
oP4=torch.empty(M,N,device="cuda");oBI=torch.empty(M,N,device="cuda");oB1=torch.empty(M,N,device="cuda")
_k[(1,)](x,y,oP4,oBI,oB1,M,K,N); torch.cuda.synchronize()
ref=x.double()@y.double(); rmx=ref.abs().max().item()
for nm,o in [("P4_4acc",oP4),("BUILTIN_tf32x3",oBI),("BUILTIN_tf32(1pass)",oB1)]:
    e=(o.double()-ref).abs().max().item(); d=(o-oBI).abs().max().item()
    print(f"{nm:22s}: relerr={e/rmx:.3e}  |x-builtin_x3|/refmax={d/rmx:.3e}")

